// Fenêtre 24 h + déduplication par similarité de titre.
const cutoff = Date.now() - 24 * 3600 * 1000;
const seen = new Map();
for (const item of $input.all()) {
  const j = item.json;
  const ts = new Date(j.isoDate || j.pubDate || Date.now()).getTime();
  if (ts < cutoff) continue;
  const key = (j.title || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').split(' ').slice(0, 6).join(' ');
  if (!key) continue;
  if (seen.has(key)) { seen.get(key).sources.push(j.link); continue; }
  seen.set(key, { title: j.title, summary: (j.contentSnippet || '').slice(0, 600), link: j.link, sources: [j.link], date: new Date(ts).toISOString().slice(0, 10) });
}
return [...seen.values()].map(json => ({ json }));

// Assemblage du deck. Contrôle qualité : sous 20 cartes valides, on conserve la veille.
const raw = $input.first().json.content?.[0]?.text || '{}';
let parsed;
try { parsed = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch { parsed = { items: [] }; }

const briefs = (parsed.items || [])
  .filter(i => i.title && i.body && i.source)
  .slice(0, 8)
  .map((i, n) => ({
    id: `brief-${new Date().toISOString().slice(0,10)}-${n}`,
    type: 'brief',
    theme: 'actualite',
    difficulty: 1,
    payload: { title: i.title, body: i.body },
    sources: [{ name: i.source, date: i.date }]
  }));

return [{ json: { date: new Date().toISOString().slice(0,10), generatedAt: new Date().toISOString(), briefs, count: briefs.length, ok: briefs.length >= 5 } }];
